// Get the incoming data
let data = $input.item.json.output ?? $input.item.json;

// If AI returned JSON as a string, convert it to an object
if (typeof data === "string") {
    try {
        data = JSON.parse(data);
    } catch (error) {
        return {
            json: {
                ...$input.item.json,
                isValid: false,
                validationError: "AI output is not valid JSON",
                rawOutput: data
            }
        };
    }
}

// Make absolutely sure data is an object
if (!data || typeof data !== "object" || Array.isArray(data)) {
    return {
        json: {
            ...$input.item.json,
            isValid: false,
            validationError: "AI output is not a valid object",
            rawOutput: data
        }
    };
}

// Validate required invoice fields
const isValid =
    Boolean(data.vendor_name) &&
    Boolean(data.total);

// Return a proper n8n item
return {
    json: {
        ...data,
        isValid: isValid
    }
};

const clean = (value, fallback = "N/A") => {
  if (value === null || value === undefined) return fallback;
  let text = String(value)
    .replace(/\\+vert\{\}/gi, "")
    .replace(/\{\\*vert\}/gi, "")
    .replace(/\r\n/g, "\n")
    .replace(/\r/g, "\n")
    .trim();
  return text || fallback;
};

const get = (item, ...keys) => {
  for (const key of keys) {
    if (item[key] !== undefined && item[key] !== null && String(item[key]).trim() !== "") {
      return clean(item[key]);
    }
  }
  return "N/A";
};

// Process input items safely
return $input.all().map((item, index) => {
  const json = item.json;

  const vendor = get(json, "vendor_name", "Vendor", "vendor", "vendor_name");
  const kraPin = get(json, "vendor_kra_pin", "Vendor KRA PIN", "KRA PIN", "kra_pin");
  const date = get(json, "date", "Date", "receipt_date", "transaction_date");

  // Dynamic Sequence ID calculation (01/date/001, 002, etc.)
  const rawSeq = get(json, "Sequence ID", "sequence_id", "SequenceID", "transaction_uid");
  const sequenceID = rawSeq !== "N/A" ? rawSeq : `01/${date !== "N/A" ? date : "24-07-2026"}/${String(index + 1).padStart(3, '0')}`;

  const time = get(json, "time", "Time", "receipt_time");
  const transactionNumber = get(json, "transaction_number", "Transaction Number", "Transaction No", "transaction_no");
  const registerNumber = get(json, "register_number", "Register Number", "Register No", "register_no");
  const cashier = get(json, "cashier", "Cashier", "cashier_name");
  const servedBy = get(json, "served_by", "Served By", "servedBy", "server");
  const customerName = get(json, "customer_name", "Customer Name", "customer");
  const taxableAmount = get(json, "taxable_amount", "Taxable Amount", "taxable");
  const vatAmount = get(json, "vat_amount", "VAT Amount", "VAT", "vat");
  const totalAmount = get(json, "total_amount", "Total Amount", "Total", "total");
  const etimsInvoice = get(json, "etims_invoice_number", "eTIMS Invoice Number", "etims_invoice", "invoice_number");
  const imageURL = get(json, "image_url", "Image URL", "ImageURL");

  let items = json["items"] || json["Items Purchased"] || json["items_purchased"] || [];
  if (typeof items === "string") {
    try { items = JSON.parse(items); } catch { items = []; }
  }

  return {
    json: {
      ...json,
      "Sequence ID": sequenceID,
      "Vendor": vendor,
      "Vendor KRA PIN": kraPin,
      "Date": date,
      "Time": time,
      "Transaction Number": transactionNumber,
      "Register Number": registerNumber,
      "Cashier": cashier,
      "Served By": servedBy,
      "Customer Name": customerName,
      "Taxable Amount": taxableAmount,
      "VAT Amount": vatAmount,
      "Total Amount": totalAmount,
      "eTIMS Invoice Number": etimsInvoice,
      "Image URL": imageURL,
      "Items Purchased": items
    }
  };
});

const items = $input.all();

for (const item of items) {
    const totalAmount = item.json.Total_Amount || item.json.total || 0;

    // Example policy check: Flag if amount exceeds maximum allowed limit (e.g., 50000)
    item.json.policyPassed = totalAmount <= 50000;
}

return items;

